def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c

    if n >= 95:
        if opp_d * 4 <= n and opp[-5:].count('D') <= 1:
            return 'C'
        return 'D'

    if n >= 10:
        recent_opp = opp[-10:]
        recent_d = recent_opp.count('D')
        if recent_d >= 8:
            return 'D'
        if recent_d == 0 and last_opp == 'C':
            if n >= 20 and n % 17 == 0:
                return 'D'
            return 'C'

    if n >= 20 and opp_d == 0:
        if n % 13 == 0:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            run_dd = 0
            for i in range(n - 1, -1, -1):
                if me[i] == 'D' and opp[i] == 'D':
                    run_dd += 1
                else:
                    break
            if run_dd >= 4:
                if rng.random() < 0.3:
                    return 'C'
                return 'D'
            if n >= 4 and opp[-4:].count('D') >= 3:
                return 'D'
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        else:
            if opp_d >= 10 and opp_c >= 10:
                return 'D'
            if rng.random() < 0.2:
                return 'D'
            return 'C'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        run_c = 0
        for a in reversed(opp):
            if a == 'C':
                run_c += 1
            else:
                break
        if run_c >= 5 and n >= 20:
            if rng.random() < 0.12:
                return 'D'
        return 'C'

    return 'C'
